import{_ as a,a0 as d,w as o,s,I as e,x as i,ao as p,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"LFCS 系列第三講：歸檔/壓縮文件及目錄、設置文件屬性和搜索文件 | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 系列第三講：歸檔/壓縮文件及目錄、設置文件屬性和搜索文件 | LCTT (LFCS) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 系列第三講：歸檔/壓縮文件及目錄、設置文件屬性和搜索文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 系列第三講：歸檔/壓縮文件及目錄、設置文件屬性和搜索文件 | LCTT (LFCS) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LFCS/Part 3 - LFCS--How to Archive or Compress Files and Directories Setting File Attributes and Finding Files in Linux","title":"LFCS 系列第三講：歸檔/壓縮文件及目錄、設置文件屬性和搜索文件","tag":"LFCS","desc":""},"relativePath":"LFCS/Part 3 - LFCS--How to Archive or Compress Files and Directories Setting File Attributes and Finding Files in Linux.md","filePath":"[post].md"}'),m={name:"LFCS/Part 3 - LFCS--How to Archive or Compress Files and Directories Setting File Attributes and Finding Files in Linux.md"};function f(g,t,u,x,c,w){const l=d("Link");return o(),s("div",null,[t[20]||(t[20]=e("h1",{id:"lfcs-系列第三講-歸檔-壓縮文件及目錄、設置文件屬性和搜索文件",tabindex:"-1"},[i("LFCS 系列第三講：歸檔/壓縮文件及目錄、設置文件屬性和搜索文件 "),e("a",{class:"header-anchor",href:"#lfcs-系列第三講-歸檔-壓縮文件及目錄、設置文件屬性和搜索文件","aria-label":"Permalink to “LFCS 系列第三講：歸檔/壓縮文件及目錄、設置文件屬性和搜索文件”"},"​")],-1)),t[21]||(t[21]=e("p",null,"最近，Linux 基金會發起了一個全新的 LFCS（Linux Foundation Certified Sysadmin，Linux 基金會認證系統管理員）認證，旨在讓遍佈全世界的人都有機會參加該認證的考試，通過考試的人將表明他們有能力在 Linux 上執行基本的中級系統管理任務。這項認證包括了對已運行的系統和服務的支持、一流水平的問題解決和分析以及決定何時將問題反映給工程師團隊的能力。",-1)),t[22]||(t[22]=e("p",null,[e("img",{src:"http://www.tecmint.com/wp-content/uploads/2014/10/lfcs-Part-3.png",alt:"Linux Foundation Certified Sysadmin – Part 3"})],-1)),t[23]||(t[23]=e("p",null,[e("em",null,"LFCS 系列第三講")],-1)),t[24]||(t[24]=e("p",null,"請看以下視頻，這裏邊講給出 Linux 基金會認證程序的一些想法。",-1)),t[25]||(t[25]=e("p",null,"注：youtube 視頻",-1)),t[26]||(t[26]=e("iframe",{width:"720",height:"405",frameborder:"0",allowfullscreen:"allowfullscreen",src:"//www.youtube.com/embed/Y29qZ71Kicg"},null,-1)),t[27]||(t[27]=p(`<p>本講是系列教程中的第三講，在這一講中，我們會涵蓋如何在文件系統中歸檔/壓縮文件及目錄、設置文件屬性和搜索文件等內容，這些都是 LFCS 認證中必須掌握的知識。</p><h3 id="歸檔和壓縮的相關工具" tabindex="-1">歸檔和壓縮的相關工具 <a class="header-anchor" href="#歸檔和壓縮的相關工具" aria-label="Permalink to “歸檔和壓縮的相關工具”">​</a></h3><p>文件歸檔工具將一堆文件整合到一個單獨的歸檔文件之後，我們可以將歸檔文件備份到不同類型的介質或者通過網絡傳輸和發送 Email 來備份。在 Linux 中使用頻率最高的歸檔實用工具是 tar。當歸檔工具和壓縮工具一起使用的時候，可以減少同一文件和信息在硬盤中的存儲空間。</p><h4 id="tar-使用工具" tabindex="-1">tar 使用工具 <a class="header-anchor" href="#tar-使用工具" aria-label="Permalink to “tar 使用工具”">​</a></h4><p>tar 將一組文件打包到一個單獨的歸檔文件（通常叫做 tar 文件或者 tarball）。tar 這個名稱最初代表磁帶存檔程序（tape archiver），但現在我們可以用它來歸檔任意類型的可讀寫介質上邊的數據，而不是隻能歸檔磁帶數據。tar 通常與 gzip、bzip2 或者 xz 等壓縮工具一起使用，生成一個壓縮的 tarball。</p><p><strong>基本語法：</strong></p><pre><code># tar [選項] [路徑名 ...]
</code></pre><p>其中 ... 代表指定哪些文件進行歸檔操作的表達式</p><h4 id="tar-的常用命令" tabindex="-1">tar 的常用命令 <a class="header-anchor" href="#tar-的常用命令" aria-label="Permalink to “tar 的常用命令”">​</a></h4><div class="table-wrap"><table><thead><tr><th>長選項</th><th style="text-align:center;">簡寫</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td>-create</td><td style="text-align:center;">c</td><td style="text-align:left;">創建 tar 歸檔文件</td></tr><tr><td>-concatenate</td><td style="text-align:center;">A</td><td style="text-align:left;">將一存檔與已有的存檔合併</td></tr><tr><td>-append</td><td style="text-align:center;">r</td><td style="text-align:left;">把要存檔的文件追加到歸檔文件的末尾</td></tr><tr><td>-update</td><td style="text-align:center;">u</td><td style="text-align:left;">更新新文件到歸檔文件中去</td></tr><tr><td>-diff 或 -compare</td><td style="text-align:center;">d</td><td style="text-align:left;">比較存檔與當前文件的不同之處</td></tr><tr><td>-file archive</td><td style="text-align:center;">f</td><td style="text-align:left;">使用檔案文件或歸檔設備</td></tr><tr><td>-list</td><td style="text-align:center;">t</td><td style="text-align:left;">列出 tarball 中的內容</td></tr><tr><td>-extract 或 -get</td><td style="text-align:center;">x</td><td style="text-align:left;">從歸檔文件中釋放文件</td></tr></tbody></table></div><h4 id="常用的操作修飾符" tabindex="-1">常用的操作修飾符 <a class="header-anchor" href="#常用的操作修飾符" aria-label="Permalink to “常用的操作修飾符”">​</a></h4><p>注：表格</p><div class="table-wrap"><table><thead><tr><th>長選項</th><th style="text-align:center;">縮寫</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td>-directory dir</td><td style="text-align:center;">C</td><td style="text-align:left;">執行歸檔操作前，先轉到指定目錄</td></tr><tr><td>-same-permissions</td><td style="text-align:center;">p</td><td style="text-align:left;">保持原始的文件權限</td></tr><tr><td>-verbose</td><td style="text-align:center;">v</td><td style="text-align:left;">列出所有的讀取或提取的文件。但這個標識符與 -list 一起使用的時候，還會顯示出文件大小、屬主和時間戳的信息</td></tr><tr><td>-verify</td><td style="text-align:center;">W</td><td style="text-align:left;">寫入存檔後進行校驗</td></tr><tr><td>-exclude file</td><td style="text-align:center;"></td><td style="text-align:left;">不把指定文件包含在內</td></tr><tr><td>-exclude=pattern</td><td style="text-align:center;">X</td><td style="text-align:left;">以PATTERN模式排除文件</td></tr><tr><td>-gzip 或 -gunzip</td><td style="text-align:center;">z</td><td style="text-align:left;">通過gzip壓縮歸檔</td></tr><tr><td>-bzip2</td><td style="text-align:center;">j</td><td style="text-align:left;">通過bzip2壓縮歸檔</td></tr><tr><td>-xz</td><td style="text-align:center;">J</td><td style="text-align:left;">通過xz壓縮歸檔</td></tr></tbody></table></div><p>Gzip 是最古老的壓縮工具，壓縮率最小，bzip2 的壓縮率稍微高一點。另外，xz 是最新的壓縮工具，壓縮率最好。xz 具有最佳壓縮率的代價是：完成壓縮操作花費最多時間，壓縮過程中佔有較多系統資源。</p><p>通常，通過這些工具壓縮的 tar 文件相應的具有 .gz、.bz2 或 .xz的擴展名。在下列的例子中，我們使用 file1、file2、file3、file4 和 file5 進行演示。</p><p><strong>通過 gzip、bzip2 和 xz 壓縮歸檔</strong></p><p>歸檔當前工作目錄的所有文件，並以 gzip、bzip2 和 xz 壓縮剛剛的歸檔文件（請注意，用正則表達式來指定哪些文件應該歸檔——這是為了防止將歸檔工具包前一步生成的文件打包進來）。</p><pre><code># tar czf myfiles.tar.gz file[0-9]
# tar cjf myfiles.tar.bz2 file[0-9]
# tar cJf myfile.tar.xz file[0-9]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Compress-Multiple-Files.png" alt="Compress Multiple Files Using tar"></p><p><em>壓縮多個文件</em></p><p><strong>列舉 tarball 中的內容和更新/追加文件到歸檔文件中</strong></p><p>列舉 tarball 中的內容，並顯示相同信息為一個詳細目錄清單。注意，不能直接向壓縮的歸檔文件更新/追加文件（若你需要向壓縮的 tarball 中更新/追加文件，需要先解壓 tar 文件後再進行操作，然後重新壓縮）。</p><pre><code># tar tvf [tarball]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/List-Archive-Content.png" alt="Check Files in tar Archive"></p><p><em>列舉歸檔文件中的內容</em></p><p>運行一下任意一條命令：</p><pre><code># gzip -d myfiles.tar.gz	[#1]
# bzip2 -d myfiles.tar.bz2	[#2]
# xz -d myfiles.tar.xz 		[#3]
</code></pre><p>然後：</p><pre><code># tar --delete --file myfiles.tar file4 (刪除tarball中的file4)
# tar --update --file myfiles.tar file4 (更新tarball中的file4)
</code></pre><p>和</p><pre><code># gzip myfiles.tar		[ 如果你運行 #1 命令 ]
# bzip2 myfiles.tar		[ 如果你運行 #2 命令 ]
# xz myfiles.tar 		[ 如果你運行 #3 命令 ]
</code></pre><p>最後</p><pre><code># tar tvf [tarball] #again
</code></pre><p>將 file4 修改後的日期和時間與之前顯示的對應信息進行比較</p><p><strong>排除文件類型</strong></p><p>假設你現在需要備份用户的家目錄。一個有經驗的系統管理員會選擇忽略所有視頻和音頻文件再備份（也可能是公司規定）。</p><p>可能你最先想到的方法是在備份的時候，忽略擴展名為 .mp3 和 .mp4（或者其他格式）的文件。但如果你有些自作聰明的用户將擴展名改為 .txt 或者 .bkp，那你的方法就不靈了。為了發現並排除音頻或者視頻文件，你需要先檢查文件類型。以下 shell 腳本可以代你完成類型檢查：</p><pre><code>#!/bin/bash
# 把需要進行備份的目錄傳遞給 $1 參數.
DIR=$1
# 排除文件類型中包含了 mpeg 字符串的文件，然後創建 tarball 並進行壓縮。
# -若文件類型中包含 mpeg 字符串， $?（最後執行的命令的退出狀態）返回 0，然後文件名被定向到排除選項。否則返回 1。
# -若 $? 等於 0，該文件從需要備份文件的列表排除。
tar X &lt;(for i in $DIR/*; do file $i | grep -i mpeg; if [ $? -eq 0 ]; then echo $i; fi;done) -cjf backupfile.tar.bz2 $DIR/*
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Exclude-Files-in-Tar.png" alt="Exclude Files in tar Archive"></p><p><em>排除文件進行備份</em></p><p><strong>使用 tar 保持文件的原有權限進行恢復</strong></p><p>通過以下命令，你可以保留文件的權限將備份文件恢復到原始用户的家目錄（本例是 user_restore）。</p><pre><code># tar xjf backupfile.tar.bz2 --directory user_restore --same-permissions
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Restore-tar-Backup-Files.png" alt="Restore Files from tar Archive"></p><p><em>從歸檔文件中恢復</em></p><p><strong>擴展閲讀：</strong></p>`,46)),e("ul",null,[e("li",null,[n(l,{href:"http://www.tecmint.com/18-tar-command-examples-in-linux/"},{default:r(()=>[...t[0]||(t[0]=[i("18 tar Command Examples in Linux",-1)])]),_:1})]),e("li",null,[n(l,{href:"http://www.tecmint.com/dtrx-an-intelligent-archive-extraction-tar-zip-cpio-rpm-deb-rar-tool-for-linux/"},{default:r(()=>[...t[1]||(t[1]=[i("Dtrx – An Intelligent Archive Tool for Linux",-1)])]),_:1})])]),t[28]||(t[28]=p(`<h3 id="通過-find-命令搜索文件" tabindex="-1">通過 find 命令搜索文件 <a class="header-anchor" href="#通過-find-命令搜索文件" aria-label="Permalink to “通過 find 命令搜索文件”">​</a></h3><p>find 命令用於遞歸搜索目錄樹中包含指定字符的文件和目錄，然後在屏幕顯示出於指定字符相匹配的文件和目錄，或者在匹配項進行其他操作。</p><p>通常，我們通過文件名、文件的屬主、屬組、類型權限、日期及大小來搜索。</p><h4 id="基本語法" tabindex="-1">基本語法：#### <a class="header-anchor" href="#基本語法" aria-label="Permalink to “基本語法：####”">​</a></h4><pre><code># find [需搜索的目錄] [表達式]
</code></pre><p><strong>通過文件大小遞歸搜索文件</strong></p><p>以下命令會搜索當前目錄（.）及其下兩層子目錄（-maxdepth 3，包含當前目錄及往下兩層的子目錄）中大於 2 MB（-size +2M）的所有文件（-f）。</p><pre><code># find . -maxdepth 3 -type f -size +2M
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Find-Files-Based-on-Size.png" alt="Find Files by Size in Linux"> * 通過文件大小搜索文件*</p><p><strong>搜索符合一定規則的文件並將其刪除</strong></p><p>有時候，777 權限的文件通常為外部攻擊者打開便利之門。不管是以何種方式，讓所有人都可以對文件進行任意操作都是不安全的。對此，我們採取一個相對激進的方法——刪除這些文件（&#39;{}&#39; + 用來“聚集”搜索的結果）。</p><pre><code># find /home/user -perm 777 -exec rm &#39;{}&#39; +
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Find-Files-with-777-Permission.png" alt="Find all 777 Permission Files"></p><p><em>搜索 777 權限的文件</em></p><p><strong>按訪問時間和修改時間搜索文件</strong></p><p>搜索 /etc 目錄下訪問時間（-atime）或修改時間（-mtime）大於（+180）或小於（-180） 6 個月或者剛好（180） 6 個月的配置文件。</p><p>按照下面例子對命令進行修改：</p><pre><code># find /etc -iname &quot;*.conf&quot; -mtime -180 -print
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Find-Modified-Files.png" alt="Find Files by Modification Time"></p><p><em>按修改時間搜索文件</em></p>`,20)),e("ul",null,[e("li",null,[t[3]||(t[3]=i("擴展閲讀： ",-1)),n(l,{href:"http://www.tecmint.com/35-practical-examples-of-linux-find-command/"},{default:r(()=>[...t[2]||(t[2]=[i("35 Practical Examples of Linux ‘find’ Command",-1)])]),_:1})])]),t[29]||(t[29]=p(`<h3 id="文件權限及基本屬性" tabindex="-1">文件權限及基本屬性 <a class="header-anchor" href="#文件權限及基本屬性" aria-label="Permalink to “文件權限及基本屬性”">​</a></h3><p>ls -l 命令輸出的前 10 位字符是文件的屬性，其中第一個字符用來表明文件的類型。</p><ul><li>– : 普通文件</li><li>-d : 目錄</li><li>-l : 符號鏈接</li><li>-c : 字符設備 (它將數據作為字節流處理，如terminal)</li><li>-b : 塊設備 (在塊設備中處理數據，如存儲設備)</li></ul><p>接下來表示文件屬性的 9 位字符叫做文件的讀寫模式，代表文件屬主、同組用户和其他用户（通常指的是“外部世界”）對應的讀（r）、寫（w）和執行（x）權限。</p><p>文件的寫權限允許對應的用户對文件進行打開和讀寫，對於同時設置了執行權限的目錄，對應用户可以列舉出該目錄的內容。另外，文件的執行權限允許將文件當做是一個可執行程序來運行，而目錄的執行權限則是允許用户進入和退出該目錄。</p><p>文件的權限通過 chown 命令來更改，其基本語法如下：</p><pre><code># chmod [new_mode] file
</code></pre><p>new_mode 可以是 3 位八進制數值或者對應權限的表達式。</p><p>八進制數值可以從二進制數值進行等值轉換，通過下列方法來計算文件屬主、同組用户和其他用户權限對應的二進制數值：</p><p>一個確定權限的二進制數值表現為 2 的冪（r=2^2，w=2^1，x=2^0），當權限省缺時，二進制數值為 0。如下：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/File-Permissions.png" alt="Linux File Permissions"></p><p><em>文件權限</em></p><p>使用八進制數值設置上圖的文件權限，請輸入：</p><pre><code># chmod 744 myfile
</code></pre><p>通過 u、g 和 o 分別代表用户、同組用户和其他用户，然後你也可以使用權限表達式來單獨對用户設置文件的權限模式。也可以通過 a 代表所有用户，然後設置文件權限。通過 + 號或者 - 號相應的賦予或移除文件權限。</p><p><strong>為所有用户撤銷一個 shell 腳本的執行權限</strong></p><p>正如之前解釋的那樣，我們可以通過 - 號為需要移除權限的屬主、同組用户、其他用户或者所有用户去掉指定的文件權限。下面命令中的短橫線（-）可以理解為：移除（-）所有用户（a）的 backup.sh 文件執行權限（x）。</p><pre><code># chmod a-x backup.sh
</code></pre><p>下面演示為文件屬主、同組用户賦予讀、寫和執行權限，並賦予其他用户讀權限。</p><p>當我們使用 3 位八進制數值為文件設置權限的時候，第一位數字代表屬主權限，第二位數字代表同組用户權限，第三位數字代表其他用户的權限：</p><ul><li>屬主：(r=2^2 + w=2^1 + x=2^0 = 7)</li><li>同組用户：(r=2^2 + w=2^1 + x=2^0 = 7)</li><li>其他用户：(r=2^2 + w=0 + x=0 = 4)</li></ul><p>命令如下：</p><pre><code># chmod 774 myfile
</code></pre><p>隨着練習時間的推移，你會知道何種情況下使用哪種方式來更改文件的權限模式的效果最好。</p><p>使用 ls -l 詳細列舉目錄詳細同樣會顯示出文件的屬主和屬組（這個很基本，而且影響到系統文件的訪問控制）。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Linux-File-Listing.png" alt="Linux File Listing"></p><p><em>列舉 Linux 文件</em></p><p>通過 chown 命令可以對文件的歸屬權進行更改，可以同時或者分開更改屬主和屬組。其基本語法為：</p><pre><code># chown user:group file
</code></pre><p>至少要指定用户或者用户組</p><p><strong>舉幾個例子：</strong></p><p>將文件的屬主更改為指定用户：</p><pre><code># chown gacanepa sent
</code></pre><p>同時將文件的屬主和屬組更改為指定的用户和組：</p><pre><code># chown gacanepa:gacanepa TestFile
</code></pre><p>只將文件的屬組更改為指定組。注意組名前的冒號（:）。</p><pre><code># chown :gacanepa email_body.txt
</code></pre><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>作為一個系統管理員，你需要懂得如何創建和恢復備份、如何在系統中搜索文件並更改它們的屬性。通過一些技巧，你可以更好地管理系統並避免以後出問題。</p><p>我希望，本文給出的技巧可以幫助你達成管理系統的目標。你可以隨時在評論中發表自己的技巧及社區給你帶來的益處。</p><p>先行感謝！</p><p>參考鏈接</p>`,42)),e("ul",null,[e("li",null,[n(l,{href:"https://training.linuxfoundation.org/certification/LFCS"},{default:r(()=>[...t[4]||(t[4]=[i("關於 LFCS",-1)])]),_:1})]),e("li",null,[n(l,{href:"https://training.linuxfoundation.org/certification/why-certify-with-us"},{default:r(()=>[...t[5]||(t[5]=[i("為什麼需要 Linux 基金會認證?",-1)])]),_:1})]),e("li",null,[n(l,{href:"https://identity.linuxfoundation.org/user?destination=pid/1"},{default:r(()=>[...t[6]||(t[6]=[i("註冊 LFCS 考試",-1)])]),_:1})])]),t[30]||(t[30]=e("hr",null,null,-1)),e("p",null,[t[8]||(t[8]=i("via: ",-1)),n(l,{href:"http://www.tecmint.com/compress-files-and-finding-files-in-linux/"},{default:r(()=>[...t[7]||(t[7]=[i("http://www.tecmint.com/compress-files-and-finding-files-in-linux/",-1)])]),_:1})]),e("p",null,[t[12]||(t[12]=i("作者：",-1)),n(l,{href:"http://www.tecmint.com/author/gacanepa/"},{default:r(()=>[...t[9]||(t[9]=[i("Gabriel Cánepa",-1)])]),_:1}),t[13]||(t[13]=i(" 譯者：",-1)),n(l,{href:"https://github.com/GHLandy"},{default:r(()=>[...t[10]||(t[10]=[i("GHLandy",-1)])]),_:1}),t[14]||(t[14]=i(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[11]||(t[11]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[17]||(t[17]=i("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[15]||(t[15]=[i("LCTT",-1)])]),_:1}),t[18]||(t[18]=i(" 原創翻譯，",-1)),n(l,{href:"https://linux.cn/"},{default:r(()=>[...t[16]||(t[16]=[i("Linux中國",-1)])]),_:1}),t[19]||(t[19]=i(" 榮譽推出",-1))])])}const F=a(m,[["render",f]]);export{y as __pageData,F as default};
